--- page.tsx ---
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { MarketingHeader } from "@/components/marketing/MarketingHeader";
import { MarketingFooter } from "@/components/marketing/MarketingFooter";
import { ArticleJsonLd, FaqJsonLd } from "@/components/marketing/StructuredData";
import { BlogPostView, type QuickFact, type RelatedItem } from "@/components/marketing/blogtemplate/BlogPostView";
import {
  getPublishedPost,
  getRelatedPosts,
  productLinkForPost,
  renderArticle,
  firstParagraph,
  accentForPost,
  iconForPost,
  authorInitials,
  formatDate,
  readMinutes,
  APP_URL,
} from "@/lib/blog";

export const dynamic = "force-dynamic";

type Params = { params: Promise<{ slug: string }> };

export async function generateMetadata({ params }: Params): Promise<Metadata> {
  const { slug } = await params;
  const post = await getPublishedPost(slug);
  if (!post) return { title: "Post not found" };

  const title = post.seoTitle || post.title;
  const description = post.seoDescription || post.excerpt || `${post.title} — a guide from the Nxeon blog.`;
  // Absolute cover URL for social cards, when the post has one.
  const ogImage = post.coverImage
    ? post.coverImage.startsWith("http")
      ? post.coverImage
      : `${APP_URL}${post.coverImage}`
    : undefined;
  return {
    title,
    description,
    alternates: { canonical: `/blog/${post.slug}` },
    openGraph: {
      type: "article",
      title,
      description,
      url: `${APP_URL}/blog/${post.slug}`,
      publishedTime: (post.publishedAt ?? post.createdAt).toISOString(),
      modifiedTime: post.updatedAt.toISOString(),
      authors: [post.author],
      tags: post.tags,
      ...(ogImage ? { images: [ogImage] } : {}),
    },
    twitter: { card: "summary_large_image", title, description, ...(ogImage ? { images: [ogImage] } : {}) },
  };
}

export default async function BlogPostPage({ params }: Params) {
  const { slug } = await params;
  const post = await getPublishedPost(slug);
  if (!post) notFound();

  const { html, toc, faq } = renderArticle(post.body);
  const published = post.publishedAt ?? post.createdAt;
  const relatedPosts = await getRelatedPosts(post, 3);
  const product = productLinkForPost(post);
  const mins = readMinutes(post.body);

  // GEO "quick answer": a direct one-liner answer engines can lift, plus a few
  // genuinely useful facts pulled from the real post fields.
  const answer = (post.excerpt || firstParagraph(post.body)).trim();
  const facts: QuickFact[] = [
    { label: "Topic", value: post.category },
    { label: "Read time", value: `${mins} min read` },
    ...(post.tags.length ? [{ label: "Covers", value: post.tags.slice(0, 3).join(", ") }] : []),
    { label: "Last updated", value: formatDate(post.updatedAt) },
  ].slice(0, 4);
  const quickAnswer = answer ? { answer, facts } : null;

  // Only surface an "Updated" pill when the post was genuinely revised after
  // publishing (more than a day later).
  const updatedLabel =
    post.updatedAt.getTime() - published.getTime() > 24 * 60 * 60 * 1000
      ? `Updated ${formatDate(post.updatedAt)}`
      : null;

  const related: RelatedItem[] = relatedPosts.map((r) => ({
    slug: r.slug,
    title: r.title,
    category: r.category,
    readMins: readMinutes(r.body),
    coverImage: r.coverImage,
    iconName: iconForPost(r),
  }));

  return (
    <div className="flex min-h-screen flex-col">
      <MarketingHeader />
      <main className="flex-1">
        <ArticleJsonLd
          title={post.seoTitle || post.title}
          description={post.seoDescription || post.excerpt}
          slug={post.slug}
          published={published.toISOString()}
          updated={post.updatedAt.toISOString()}
          author={post.author}
          image={post.coverImage}
        />
        {faq.length > 0 && <FaqJsonLd items={faq} />}

        <BlogPostView
          title={post.title}
          deck={post.excerpt}
          category={post.category}
          author={post.author}
          authorInitials={authorInitials(post.author)}
          dateLabel={formatDate(published)}
          updatedLabel={updatedLabel}
          readingLabel={`${mins} min read`}
          accent={accentForPost(post)}
          coverImage={post.coverImage}
          iconName={iconForPost(post)}
          tags={post.tags}
          contentHtml={html}
          toc={toc}
          quickAnswer={quickAnswer}
          product={product}
          related={related}
        />
      </main>
      <MarketingFooter />
    </div>
  );
}

--- BlogPostView ---
"use client";

/**
 * BlogPostView — the editorial article shell for REAL blog posts.
 *
 * This is the production sibling of the preview-only BlogArticle.tsx: it wears
 * the same design language (art/gradient banner hero, byline + reading time, a
 * sticky table-of-contents "spine" that fills with reading progress and
 * scroll-spies the active section, a slim top progress bar, a GEO "quick answer"
 * box, styled long-form body, product CTA rails and a related-posts strip) but
 * every value is driven by plain, serialisable props derived from a BlogPost
 * row in app/blog/[slug]/page.tsx. It degrades gracefully when a post has no
 * cover image (gradient + topic icon) or no TOC-able headings (full-width body,
 * no spine). All iconography comes from components/marketing/icons — no emoji.
 */

import Link from "next/link";
import { useEffect, useRef, useState } from "react";
import { usePrefersReducedMotion, StarRow } from "@/components/marketing/gamelanding/kit";
import {
  IconBolt,
  IconArrow,
  IconClock,
  IconGame,
  IconGlobe,
  IconMail,
  IconShield,
  IconBackup,
  IconTerminal,
  IconGauge,
  IconApps,
  IconScale,
  IconServer,
  IconSpark,
} from "@/components/marketing/icons";

const ICONS: Record<string, (p: { size?: number; className?: string }) => React.ReactElement> = {
  game: IconGame,
  globe: IconGlobe,
  mail: IconMail,
  shield: IconShield,
  backup: IconBackup,
  terminal: IconTerminal,
  gauge: IconGauge,
  apps: IconApps,
  scale: IconScale,
  server: IconServer,
};
function iconFor(name: string) {
  return ICONS[name] ?? IconServer;
}

export type TocItem = { id: string; label: string; level: 2 | 3 };
export type QuickFact = { label: string; value: string };
export type RelatedItem = {
  slug: string;
  title: string;
  category: string;
  readMins: number;
  coverImage: string | null;
  iconName: string;
};
export type ProductLink = { label: string; href: string; blurb: string };

export type BlogPostViewProps = {
  title: string;
  deck: string;
  category: string;
  author: string;
  authorInitials: string;
  dateLabel: string;
  updatedLabel: string | null;
  readingLabel: string;
  accent: string;
  coverImage: string | null;
  iconName: string;
  tags: string[];
  contentHtml: string;
  toc: TocItem[];
  quickAnswer: { answer: string; facts: QuickFact[] } | null;
  product: ProductLink;
  related: RelatedItem[];
};

/* ── reading progress (0→1) across the article body ──────────────────────── */
function useReadingProgress<T extends HTMLElement>() {
  const ref = useRef<T | null>(null);
  const [p, setP] = useState(0);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    let raf = 0;
    const compute = () => {
      raf = 0;
      const r = el.getBoundingClientRect();
      const vh = window.innerHeight || 1;
      const total = r.height - vh;
      const travelled = -r.top;
      setP(total <= 0 ? 1 : Math.max(0, Math.min(1, travelled / total)));
    };
    const onScroll = () => {
      if (!raf) raf = requestAnimationFrame(compute);
    };
    compute();
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll, { passive: true });
    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
      if (raf) cancelAnimationFrame(raf);
    };
  }, []);
  return { ref, p };
}

/* ── scroll-spy: which section id is currently in view ───────────────────── */
function useScrollSpy(ids: string[]) {
  const [active, setActive] = useState(ids[0] ?? "");
  useEffect(() => {
    if (typeof IntersectionObserver === "undefined" || ids.length === 0) return;
    const seen = new Map<string, number>();
    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) seen.set(e.target.id, e.intersectionRatio);
        let best = "";
        let bestRatio = -1;
        for (const [id, ratio] of seen) {
          if (ratio > bestRatio) {
            best = id;
            bestRatio = ratio;
          }
        }
        if (best && bestRatio > 0) setActive(best);
      },
      { rootMargin: "-20% 0px -55% 0px", threshold: [0, 0.25, 0.5, 1] },
    );
    for (const id of ids) {
      const el = document.getElementById(id);
      if (el) io.observe(el);
    }
    return () => io.disconnect();
  }, [ids]);
  return active;
}

export function BlogPostView(props: BlogPostViewProps) {
  const {
    title,
    deck,
    category,
    author,
    authorInitials,
    dateLabel,
    updatedLabel,
    readingLabel,
    accent,
    coverImage,
    iconName,
    tags,
    contentHtml,
    toc,
    quickAnswer,
    product,
    related,
  } = props;

  const reduced = usePrefersReducedMotion();
  const [imgOk, setImgOk] = useState(true);
  const { ref: bodyRef, p } = useReadingProgress<HTMLDivElement>();
  const ids = toc.map((t) => t.id);
  const active = useScrollSpy(ids);
  const HeroIcon = iconFor(iconName);
  const hasCover = Boolean(coverImage) && imgOk;
  const hasToc = toc.length >= 2;

  return (
    <div className="relative">
      {/* slim top reading-progress bar */}
      <div className="fixed inset-x-0 top-0 z-[70] h-[3px] bg-transparent" aria-hidden>
        <div
          className="h-full origin-left"
          style={{
            width: `${p * 100}%`,
            background: `linear-gradient(90deg, ${accent}, #3b82f6, #22d3ee)`,
            boxShadow: `0 0 12px ${accent}88`,
          }}
        />
      </div>

      {/* ── BANNER HERO ──────────────────────────────────────────────────── */}
      <header className="relative overflow-hidden">
        <div className="absolute inset-0 -z-10">
          {hasCover ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={coverImage as string}
              alt=""
              onError={() => setImgOk(false)}
              className={`h-full w-full object-cover object-center ${reduced ? "" : "pv-kenburns"}`}
            />
          ) : (
            <div className="hero-aura absolute inset-0" />
          )}
          <div className="absolute inset-0 bg-gradient-to-t from-navy-950 via-navy-950/85 to-navy-950/55" />
          <div
            className="absolute inset-0"
            style={{ background: `radial-gradient(70% 60% at 20% 100%, ${accent}22, transparent 65%)` }}
          />
        </div>

        <div className="rail flex min-h-[52vh] flex-col justify-end pb-12 pt-28 sm:min-h-[58vh]">
          <div className="max-w-3xl">
            <div className="mb-5">
              <Link href="/blog" className="inline-flex items-center gap-1.5 text-sm text-slate-300 transition-colors hover:text-white">
                <IconArrow size={15} className="rotate-180" /> All guides
              </Link>
            </div>
            <div className="flex items-center gap-3">
              <span
                className="flex h-9 w-9 items-center justify-center rounded-lg border"
                style={{ borderColor: `${accent}33`, background: `${accent}18`, color: accent }}
              >
                <HeroIcon size={18} />
              </span>
              <span className="eyebrow" style={{ color: accent }}>
                {category}
              </span>
            </div>
            <h1 className="mt-5 text-3xl font-black leading-[1.08] tracking-tight text-white sm:text-4xl lg:text-[3rem]">
              {title}
            </h1>
            {deck && <p className="mt-5 max-w-2xl text-lg leading-relaxed text-slate-200/90">{deck}</p>}

            {/* byline row */}
            <div className="mt-7 flex flex-wrap items-center gap-x-5 gap-y-3 text-sm text-slate-300">
              <span className="flex items-center gap-2.5">
                <span
                  className="flex h-9 w-9 items-center justify-center rounded-full text-xs font-semibold text-white"
                  style={{ background: `linear-gradient(135deg, ${accent}, #3b82f6)` }}
                >
                  {authorInitials}
                </span>
                <span>
                  <span className="block font-semibold text-white">{author}</span>
                  <span className="block text-xs text-slate-400">Nxeon editorial</span>
                </span>
              </span>
              <span className="hidden h-8 w-px bg-white/15 sm:block" />
              <span className="text-slate-400">{dateLabel}</span>
              <span className="inline-flex items-center gap-1.5 text-slate-400">
                <IconClock size={15} /> {readingLabel}
              </span>
              {updatedLabel && (
                <span
                  className="inline-flex items-center gap-1.5 rounded-full border px-3 py-1 text-xs font-medium"
                  style={{ borderColor: `${accent}44`, color: "#e2e8f0", background: `${accent}14` }}
                >
                  {updatedLabel}
                </span>
              )}
            </div>
          </div>
        </div>
      </header>

      {/* ── BODY: sticky TOC spine + article ─────────────────────────────── */}
      <div ref={bodyRef} className={`rail grid gap-10 py-14 ${hasToc ? "lg:grid-cols-12 lg:gap-14" : ""}`}>
        {/* TOC SPINE (sticky, desktop) — only when there are enough headings */}
        {hasToc && (
          <aside className="hidden lg:col-span-3 lg:block">
            <div className="sticky top-24">
              <p className="section-label mb-4">On this page</p>
              <nav className="relative pl-5">
                <div className="absolute bottom-1 left-[3px] top-1 w-px bg-white/10" aria-hidden />
                <div
                  className="absolute left-[3px] top-1 w-px"
                  style={{
                    height: `calc(${(reduced ? 1 : p) * 100}% - 8px)`,
                    maxHeight: "calc(100% - 8px)",
                    background: `linear-gradient(to bottom, ${accent}, #3b82f6)`,
                    transition: reduced ? "none" : "height 0.15s linear",
                  }}
                  aria-hidden
                />
                <ul className="space-y-3.5">
                  {toc.map((t) => {
                    const on = active === t.id;
                    return (
                      <li key={t.id} className={`relative ${t.level === 3 ? "pl-3" : ""}`}>
                        <span
                          className="absolute -left-[18px] top-1.5 h-2 w-2 rounded-full ring-4 ring-navy-950 transition-colors"
                          style={{ background: on ? accent : "rgba(255,255,255,0.2)" }}
                          aria-hidden
                        />
                        <a
                          href={`#${t.id}`}
                          className={`block text-sm transition-colors ${on ? "font-semibold text-white" : "text-slate-400 hover:text-slate-200"}`}
                        >
                          {t.label}
                        </a>

--- lib/blog.ts ---
import { db } from "@/lib/db";
import type { BlogPost } from "@prisma/client";

export const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

/* ----------------------------------------------------------------------------
 * Fetch helpers
 * ------------------------------------------------------------------------- */

/** Published posts, newest first — for the public blog index. */
export function getPublishedPosts(): Promise<BlogPost[]> {
  return db.blogPost.findMany({
    where: { published: true },
    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
  });
}

/** A single published post by slug, or null (drives notFound() on the page). */
export function getPublishedPost(slug: string): Promise<BlogPost | null> {
  return db.blogPost.findFirst({ where: { slug, published: true } });
}

/**
 * Full-text-ish search over published posts. Case-insensitive `contains` across
 * title / excerpt / body, plus an exact tag match. Empty query falls back to the
 * normal newest-first listing. Runs server-side so results are crawlable.
 */
export function searchPublishedPosts(q: string): Promise<BlogPost[]> {
  const query = q.trim();
  if (!query) return getPublishedPosts();
  return db.blogPost.findMany({
    where: {
      published: true,
      OR: [
        { title: { contains: query, mode: "insensitive" } },
        { excerpt: { contains: query, mode: "insensitive" } },
        { body: { contains: query, mode: "insensitive" } },
        { category: { contains: query, mode: "insensitive" } },
        { tags: { has: query.toLowerCase() } },
      ],
    },
    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
  });
}

/** Default page size for the paginated blog index. */
export const POSTS_PER_PAGE = 12;

/** Prisma `where` for the public index — optionally narrowed by a search query. */
function publishedWhere(q?: string) {
  const query = (q ?? "").trim();
  if (!query) return { published: true } as const;
  return {
    published: true,
    OR: [
      { title: { contains: query, mode: "insensitive" as const } },
      { excerpt: { contains: query, mode: "insensitive" as const } },
      { body: { contains: query, mode: "insensitive" as const } },
      { category: { contains: query, mode: "insensitive" as const } },
      { tags: { has: query.toLowerCase() } },
    ],
  };
}

export type PostsPage = {
  posts: BlogPost[];
  total: number;
  page: number;
  totalPages: number;
  perPage: number;
};

/**
 * One page of published posts (newest first), optionally filtered by a search
 * query. `page` is 1-based and clamped into range. Returns the slice plus enough
 * metadata to render prev/next controls and per-page canonicals. Runs a single
 * count + a single findMany so the index stays light even with ~200 posts.
 */
export async function getPostsPage(opts: { page?: number; q?: string; perPage?: number } = {}): Promise<PostsPage> {
  const perPage = Math.max(1, opts.perPage ?? POSTS_PER_PAGE);
  const where = publishedWhere(opts.q);
  const total = await db.blogPost.count({ where });
  const totalPages = Math.max(1, Math.ceil(total / perPage));
  const page = Math.min(Math.max(1, Math.floor(opts.page ?? 1)), totalPages);
  const posts = await db.blogPost.findMany({
    where,
    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
    skip: (page - 1) * perPage,
    take: perPage,
  });
  return { posts, total, page, totalPages, perPage };
}

/**
 * Up to `limit` other published posts related to `post` — same category first,
 * back-filled with the newest posts so the block is never short. The current
 * post is always excluded. Drives the "Related articles" internal-linking block
 * on the post page (the biggest lever for getting thin/orphaned posts indexed).
 */
export async function getRelatedPosts(post: BlogPost, limit = 3): Promise<BlogPost[]> {
  const sameCategory = await db.blogPost.findMany({
    where: { published: true, category: post.category, id: { not: post.id } },
    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
    take: limit,
  });
  if (sameCategory.length >= limit) return sameCategory;

  // Back-fill with the newest posts, skipping anything already picked.
  const have = new Set([post.id, ...sameCategory.map((p) => p.id)]);
  const recent = await db.blogPost.findMany({
    where: { published: true, id: { notIn: [...have] } },
    orderBy: [{ publishedAt: "desc" }, { createdAt: "desc" }],
    take: limit - sameCategory.length,
  });
  return [...sameCategory, ...recent];
}

/**
 * Map a post to the single most relevant product page so every article funnels
 * to a money page (internal-linking + conversion). Matches the post's category,
 * tags and title against product keywords; falls back to the pricing page.
 */
export function productLinkForPost(post: BlogPost): { label: string; href: string; blurb: string } {
  const hay = `${post.category} ${post.tags.join(" ")} ${post.title}`.toLowerCase();
  const has = (...ks: string[]) => ks.some((k) => hay.includes(k));

  if (has("minecraft", "rust", "game", "valheim", "palworld", "ark", "fivem", "server hosting"))
    return {
      label: "Game server hosting",
      href: "/game-servers",
      blurb: "Spin up a ready-to-play game server in minutes — one-click installs, DDoS protection and instant scaling.",
    };
  if (has("web hosting", "wordpress", "website", "php", "shared hosting"))
    return {
      label: "Web hosting",
      href: "/web-hosting",
      blurb: "Get your site online without managing a server — PHP, databases, email and free SSL, from a few dollars a month.",
    };
  if (has("domain", "dns", "nameserver"))
    return {
      label: "Register a domain",
      href: "/domains",
      blurb: "Search and register your domain, with free DNS management and one-click connection to your Nxeon services.",
    };
  if (has("email", "mailbox", "smtp"))
    return {
      label: "Business email",
      href: "/business-email",
      blurb: "Professional mailboxes on your own domain, with webmail, IMAP and spam filtering included.",
    };
  // Default: VPS is the flagship product for everything else (Linux, security,
  // Docker, self-hosting).
  return {
    label: "Cloud VPS hosting",
    href: "/vps",
    blurb: "Full root access on NVMe cloud VPS with instant deployment — the flexible way to host anything.",
  };
}

/** Every post regardless of status, newest edit first — for the admin editor. */
export function getAllPosts(): Promise<BlogPost[]> {
  return db.blogPost.findMany({ orderBy: { updatedAt: "desc" } });
}

/** Look up any post by id (admin edit form). */
export function getPostById(id: string): Promise<BlogPost | null> {
  return db.blogPost.findUnique({ where: { id } });
}

/* ----------------------------------------------------------------------------
 * Formatting
 * ------------------------------------------------------------------------- */

export function formatDate(d: Date | string | null | undefined): string {
  if (!d) return "";
  const date = typeof d === "string" ? new Date(d) : d;
  return date.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });
}

/** Rough read-time estimate from the raw markdown body. */
export function readMinutes(body: string): number {
  const words = body.trim().split(/\s+/).filter(Boolean).length;
  return Math.max(1, Math.round(words / 200));
}

/* ----------------------------------------------------------------------------
 * Tiny, self-contained markdown → HTML renderer.
 *
 * No external dependency. Handles: # / ## / ### headings, **bold**, `code`,
 * fenced ``` code blocks, - / * and 1. lists, [links](url), and blank-line
 * separated paragraphs. HTML is escaped BEFORE any markdown is applied, and
 * inline code spans are protected so their contents are never re-processed.
 * Output carries Tailwind classes so it reads well on the dark theme (there is
 * no typography plugin installed).
 * ------------------------------------------------------------------------- */

function esc(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

const CLS = {
  h1: "mt-10 mb-4 text-3xl font-bold tracking-tight text-white",
  h2: "mt-10 mb-3 text-2xl font-bold tracking-tight text-white",
  h3: "mt-8 mb-2 text-xl font-semibold text-white",
  p: "mb-4 leading-relaxed text-slate-300",
  ul: "mb-5 list-disc space-y-1.5 pl-6 text-slate-300 marker:text-brand-400",
  ol: "mb-5 list-decimal space-y-1.5 pl-6 text-slate-300 marker:text-brand-400",
  li: "leading-relaxed",
  a: "text-brand-300 underline decoration-brand-300/40 underline-offset-2 hover:text-brand-200",
  code: "rounded-md border border-white/10 bg-white/[0.06] px-1.5 py-0.5 font-mono text-[0.85em] text-brand-200",
  pre: "mb-5 overflow-x-auto rounded-xl border border-white/10 bg-navy-950/80 p-4 font-mono text-[13px] leading-relaxed text-slate-200",
  img: "w-full rounded-xl border border-white/10 shadow-lg shadow-black/20",
};

/** Allow only http(s) or root-relative image sources; reject everything else. */
function safeSrc(u: string): string {
  return /^(https?:\/\/|\/)/.test(u) ? u : "";
}

// Private-use sentinels wrap protected inline-code indices so they can never
// collide with ordinary digits in prose (e.g. "2 GB", "port 25565").
const S0 = "";
const S1 = "";

/** Inline markdown for a single run of text. */
function inline(text: string): string {
  const codes: string[] = [];
  // Protect inline code first.
  let s = esc(text).replace(/`([^`]+)`/g, (_m, c: string) => {
    codes.push(c);
    return `${S0}${codes.length - 1}${S1}`;
  });
  // Bold.
  s = s.replace(/\*\*([^*]+)\*\*/g, '<strong class="font-semibold text-white">$1</strong>');
  // Inline images ![alt](url) — MUST run before links (they share `[..](..)`).
  s = s.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, (_m, alt: string, u: string) => {
    const safe = safeSrc(u);
    if (!safe) return "";
    return `<img class="${CLS.img} my-6" src="${safe}" alt="${alt}" loading="lazy" />`;
  });
  // Links [text](url) — only http(s), root-relative, or anchors are allowed.
  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_m, t: string, u: string) => {
    const safe = /^(https?:\/\/|\/|#)/.test(u) ? u : "#";
    const ext = safe.startsWith("http");
    return `<a class="${CLS.a}" href="${safe}"${ext ? ' target="_blank" rel="noopener noreferrer"' : ""}>${t}</a>`;
  });
  // Restore inline code.

