255	/* ----------------------------------------------------------------------------
256	 * Article-aware renderer for the editorial blog template.
257	 *
258	 * Same block/inline grammar as renderMarkdown, but additionally:
259	 *   • gives every heading a stable, unique `id` so the sticky table-of-contents
260	 *     spine + scroll-spy can anchor to it,
261	 *   • returns the H2/H3 outline as a TOC, and
262	 *   • extracts any question-style heading (text ending in "?") + its following
263	 *     prose as an FAQ pair, for FAQ JSON-LD.
264	 *
265	 * Kept separate from renderMarkdown so the four other callers (admin docs,
266	 * announcements, what's-new) are completely untouched.
267	 * ------------------------------------------------------------------------- */
268	
269	export type TocEntry = { id: string; label: string; level: 2 | 3 };
270	export type FaqEntry = { q: string; a: string };
271	export type RenderedArticle = { html: string; toc: TocEntry[]; faq: FaqEntry[] };
272	
273	/** URL-safe, human-readable heading anchor. */
274	export function slugifyHeading(text: string): string {
275	  return (
276	    text
277	      .toLowerCase()
278	      .replace(/`[^`]*`/g, "")
279	      .replace(/[*_[\]()#]/g, "")
280	      .replace(/&[a-z]+;/g, "")
281	      .replace(/[^a-z0-9\s-]/g, "")
282	      .trim()
283	      .replace(/\s+/g, "-")
284	      .slice(0, 60)
285	      .replace(/^-+|-+$/g, "") || "section"
286	  );
287	}
288	
289	/** Strip inline markdown down to plain text (for FAQ answers / meta). */
290	function plainInline(text: string): string {
291	  return text
292	    .replace(/`([^`]+)`/g, "$1")
293	    .replace(/\*\*([^*]+)\*\*/g, "$1")
294	    .replace(/!\[[^\]]*\]\([^)]*\)/g, "")
295	    .replace(/\[([^\]]+)\]\([^)]+\)/g, "$1")
296	    .trim();
297	}
