300	export function firstParagraph(md: string): string {
301	  const lines = (md ?? "").replace(/\r\n/g, "\n").split("\n");
302	  const buf: string[] = [];
303	  for (const line of lines) {
304	    const t = line.trim();
305	    if (!t) {
306	      if (buf.length) break;
307	      continue;
308	    }
309	    if (/^(#{1,3}\s|[-*]\s|\d+\.\s|```|---+$|!\[)/.test(t)) {
310	      if (buf.length) break;
311	      continue;
312	    }
313	    buf.push(t);
314	  }
315	  return plainInline(buf.join(" "));
316	}
