319	  const lines = (md ?? "").replace(/\r\n/g, "\n").split("\n");
320	  const out: string[] = [];
321	  let i = 0;
322	
323	  while (i < lines.length) {
324	    const line = lines[i];
325	
326	    // Blank line — skip.
327	    if (!line.trim()) { i++; continue; }
328	
329	    // Horizontal rule.
330	    if (/^---+$/.test(line.trim())) {
331	      out.push('<hr class="my-8 border-white/[0.08]" />');
332	      i++;
333	      continue;
334	    }
335	
336	    // Standalone image line → captioned figure (not wrapped in a paragraph).
337	    const img = line.trim().match(/^!\[([^\]]*)\]\(([^)]+)\)$/);
338	    if (img) {
